content:
if (errno == EAGAIN || errno == EINTR)
                continue;

            close(fd);
            unlink(corpus_name);
            goto try_another_file_name;
        }

        total_written += r;
    }

    close(fd);
    lwan_status_debug("Request saved to %s", corpus_name);
}
